def config_vars_to_dict(config_vars):
    """
    Converts testline configuration variables represented as list with equations eg.
    ['foo=bar', 'joey=food', 'rachel=fashion'] to dictionary
    {'foo': 'bar', 'joey': 'food', 'rachel': 'fashion'}

    :param config_vars: list like ['foo=bar', 'joey=food', 'rachel=fashion']
    :return: dictionary converted from list
    :return type: dictionary
    """
    return dict([item.split('=') for item in config_vars])
